import { Elysia } from "elysia";
import { staticPlugin } from "@elysiajs/static";

const appStaticPlugin = new Elysia({
    name: 'static-plugin',
})
.use(staticPlugin({
  prefix: '/public',
  assets: 'public',
  indexHTML: false,
  alwaysStatic: true
})) 
.use(await staticPlugin({
  prefix: '/',
  assets: 'src',
  alwaysStatic: true
})) 

export default appStaticPlugin